=== NormalizeOwnerTelephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;

/**
 * Normalizes the create-owner telephone into E.164 form: strips spaces, dashes and brackets,
 * keeps a leading '+' and country code when present, otherwise assumes country code '+61' and
 * drops a single leading '0' from the national digits, requiring 8 to 15 digits after the '+'.
 * Mutates the published request in place so later steps store and return the E.164 value.
 * Rejects anything that cannot form a valid E.164 number with a 400.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerTelephoneException {
        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
        if (e164 == null) {
            throw new InvalidOwnerTelephoneException(request.getTelephone());
        }
        request.setTelephone(e164);
    }
}
=== NormalizeOwnerEmail ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;

/**
 * Normalizes the owner email when present: requires a syntactically valid address and
 * lower-cases it in place so later steps store and return the lower-cased value. An
 * absent or blank email is left untouched (email is optional). Rejects a present but
 * invalid email with a 400.
 */
public class NormalizeOwnerEmail {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerEmailException {
        String email = request.getEmail();
        if (email == null || email.trim().isEmpty()) {
            return;
        }
        if (!EMAIL.matcher(email).matches()) {
            throw new InvalidOwnerEmailException(email);
        }
        request.setEmail(email.toLowerCase(Locale.ROOT));
    }
}
=== CheckOwnerTelephoneUnique ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;

/**
 * Rejects a create-owner request whose E.164 telephone is already used by another owner with a
 * 409. Runs after {@code NormalizeOwnerTelephone}, so the request telephone is already the E.164
 * form; each existing owner's telephone is converted to E.164 the same way before comparison.
 */
public class CheckOwnerTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
                throw new DuplicateOwnerTelephoneException(request.getTelephone());
            }
        }
    }
}
=== ValidateOwnerFields ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
 * of firstName, lastName, address, city or telephone with a 400 (listing every offending
 * field) before the owner is built, then publishes the body for later steps.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}

